27	  --mono: "Cascadia Mono", Consolas, monospace;
28	}
29	* { box-sizing: border-box; }
30	body { margin: 0; background: var(--page); color: var(--text); font: 18px/1.45 var(--ui); }
31	button { font: inherit; color: inherit; cursor: pointer; }
32	.wrap { max-width: 1520px; margin: 18px auto; padding: 0 20px; }
33	.frame { background: var(--frame); border: 1px solid var(--frame-line); border-radius: 20px; padding: 18px 24px 24px;
