47	.tip p { margin: 0 0 8px; } .tip p:last-child { margin: 0; }
48	.spacer { flex: 1; }
49	.chip { display: inline-flex; align-items: center; gap: 8px; padding: 7px 14px; border-radius: 10px; border: 1px solid var(--card-line);
