241	const $ = id => document.getElementById(id);
242	const esc = s => String(s).replace(/[&<>"]/g, c => ({"&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;"}[c]));
243	const dec = (x, d = 1) => (+x).toFixed(d).replace(".", ",");
244	const plural = (n, one, few, many) => {
245	  const m10 = n % 10, m100 = n % 100;
246	  return `${n} ${m10 === 1 && m100 !== 11 ? one : m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14) ? few : many}`;
247	};
248	// «2026-10-17 10:30» → «17.10 · 10:30», с годом — «17.10.2026 · 10:30»
249	const when = (s, year) => { const [d, t] = s.split(" "), [y, m, day] = d.split("-"); return `${day}.${m}${year ? "." + y : ""} · ${t}`; };
250	const oneLine = v => JSON.stringify(v, null, 1).replace(/\n\s*/g, " ");
251	let status = null, tickets = [], current = null, controller = null, answerText = "", hits = [];
