253	function toast(text) {
254	  const t = $("toast");
255	  t.textContent = text;
256	  t.classList.add("show");
257	  clearTimeout(toast.timer);
258	  toast.timer = setTimeout(() => t.classList.remove("show"), 6000);
259	}
