267	// ---------- шапка и очередь ----------
268	async function loadStatus() {
269	  try {
270	    status = await (await fetch("/api/support/status")).json();
271	  } catch { toast("Сервер поддержки не отвечает"); return; }
272	  const o = status.ollama, ready = o.running && Object.values(o.models).every(Boolean);
273	  $("ollamaDot").className = `dot ${ready ? "on" : "off"}`;
274	  $("modelText").innerHTML = !o.running ? "Ollama не запущен — откройте его из меню «Пуск»"
275	    : !ready ? `Нет модели: ${Object.entries(o.models).filter(([, ok]) => !ok).map(([m]) => esc(m)).join(", ")}`
276	    : `<b>${esc(status.model)}</b> · Ollama ${esc(o.version)} · этот компьютер`;
277	  const crm = status.crm;
278	  $("crmDot").className = `dot ${crm.error ? "off" : "on"}`;
279	  tickets = crm.tickets || [];
280	  if (crm.error) $("crmText").textContent = `CRM недоступна: ${crm.error}`;
281	  else {
282	    $("crmText").innerHTML = `CRM: <b>${plural(tickets.length, "открытое обращение", "открытых обращения", "открытых обращений")}</b> · MCP`;
