293	      <span class="row"><span class="prio ${PRIO[t.priority] || ""}" title="приоритет ${esc(t.priority)}"></span>
294	        <span><b>${esc(t.id)}</b> · ${esc(t.status)}</span><span class="when">${when(t.created)}</span></span>
