297	    + `<button class="item free" type="button" data-id=""><span class="subj">Вопрос о продукте</span>
298	      <span class="who">без тикета — только база знаний</span></button>`;
299	  // перерисовка снимает выделение — выбранное обращение подсвечиваем снова
300	  document.querySelectorAll(".item").forEach(b => b.classList.toggle("sel", b.dataset.id === (current ? current.id : "")));
