321	      <div class="tk-title"><span class="tk-id">${esc(current.id)}</span>${esc(current.subject)}</div>
322	      <div class="tk-meta">${esc(current.user.name)} · ${esc(current.user.org)} ·
323	        <span class="st ${current.status === "в работе" ? "work" : ""}">${esc(current.status)}</span> ·
324	        приоритет ${esc(current.priority)} · ${when(current.created, true)}</div>
325	      <blockquote class="msg">${esc(current.message)}</blockquote>`
326	    : `<div class="tk-title">Вопрос о продукте</div>
327	      <div class="tk-meta">Без тикета: ассистент отвечает только по базе знаний, данные клиента не нужны</div>
328	      <div class="examples">${EXAMPLES.map(e => `<button class="example" type="button">${esc(e)}</button>`).join("")}</div>`;
329	  $("input").value = current ? current.subject : EXAMPLES[0];
330	  answerText = ""; hits = [];
331	  setCard("crm", "idle", current ? "Клиент, технические данные и прошлые обращения — из CRM через MCP"
332	    : "Без тикета — данные клиента не нужны");
333	  setCard("kb", "idle", "Три фрагмента FAQ и документации, ближайшие к вопросу");
334	  setCard("answer", "idle", "Черновик ответа клиенту со ссылками на базу знаний");
335	  $("crmHint").textContent = "MCP · crm";
336	  $("kbHint").textContent = "FAQ + README и docs/";
337	  $("answerHint").textContent = "";
338	}
339	$("ticket").addEventListener("click", e => {
340	  const b = e.target.closest(".example");
341	  if (!b) return;
342	  $("input").value = b.textContent;
343	  run();
344	});
