346	// ---------- ответ ----------
347	$("form").addEventListener("submit", e => { e.preventDefault(); controller ? controller.abort() : run(); });
348	
349	async function run() {
350	  const question = $("input").value.trim();
351	  if (!question) { toast("Напишите вопрос клиента"); return; }
352	  const ticket = current, ctrl = controller = new AbortController();
353	  $("sendBtn").textContent = "Остановить";
354	  $("sendBtn").classList.add("stop");
355	  answerText = ""; hits = [];
356	  setCard("crm", ticket ? "run" : "idle", ticket ? "Беру обращение и клиента из CRM через MCP…" : "Без тикета — данные клиента не нужны");
357	  setCard("kb", ticket ? "idle" : "run", "Ищу ближайшие фрагменты…");
358	  setCard("answer", "idle", "Модель ответит после поиска");
359	  $("answerHint").textContent = "";
360	  try {
361	    const res = await fetch("/api/support/answer", {method: "POST", headers: {"Content-Type": "application/json"},
362	      body: JSON.stringify({ticket_id: ticket ? ticket.id : null, question}), signal: ctrl.signal});
363	    if (!res.ok) throw new Error((await res.json()).detail || `HTTP ${res.status}`);
364	    const reader = res.body.getReader(), decoder = new TextDecoder();
365	    let buffer = "";
366	    for (;;) {
367	      const {value, done} = await reader.read();
368	      if (done) break;
369	      buffer += decoder.decode(value, {stream: true});
370	      let i;
371	      while ((i = buffer.indexOf("\n")) >= 0) {
372	        const line = buffer.slice(0, i).trim();
373	        buffer = buffer.slice(i + 1);
374	        if (line) handle(JSON.parse(line));
375	      }
376	    }
377	  } catch (e) {
378	    if (ctrl.signal.reason === "select") return;  // выбрали другое обращение — карточки уже сброшены
379	    if (e.name === "AbortError") { $("answerHint").textContent = "остановлено"; renderAnswer(false); }
380	    else toast(e.message);
381	  }
382	  idle();
383	  document.querySelectorAll(".card.run").forEach(c => c.classList.remove("run"));
384	}
385	
386	function handle(ev) {
387	  if (ev.type === "mcp") { renderCrm(ev); setCard("kb", "run"); }
388	  else if (ev.type === "sources") { renderKb(ev); setCard("answer", "run", '<div class="answer"><span class="cursor"></span></div>'); }
389	  else if (ev.type === "prompt") { renderPrompt(ev); }
390	  else if (ev.type === "text") { answerText += ev.text; renderAnswer(true); }
391	  else if (ev.type === "done") { renderAnswer(false); renderStats(ev); }
392	  else if (ev.type === "error") {
393	    const id = {mcp: "crm", sources: "kb", answer: "answer"}[ev.step] || "answer";
394	    setCard(id, "fail", `<div class="error">${esc(ev.message)}</div>`);
395	  }
396	}
397	
398	// ---------- ① CRM ----------
399	function renderCrm(ev) {
400	  $("crmHint").textContent = `MCP · ${ev.server.name} ${ev.server.version} · протокол ${ev.server.protocol} · ${dec(ev.seconds, 2)} с`;
401	  const got = Object.fromEntries(ev.calls.filter(c => c.ok).map(c => [c.tool, c.result]));
402	  const t = got.get_ticket, u = got.get_user;
403	  if (!t || !u) return;  // ошибку покажет событие error
404	  const past = u.tickets.filter(x => x.id !== t.id);
405	  const rows = [["Работает через", `<b>${esc(u.channel)}</b> — ${esc(u.setup)}`]];
406	  if (u.notes) rows.push(["Заметки", esc(u.notes)]);
407	  rows.push(["Прошлые обращения", past.length ? past.map(x => `<b>${esc(x.id)}</b> «${esc(x.subject)}» — ${esc(x.status)}`
408	    + (x.resolution ? `: ${esc(x.resolution)}` : "")).join("<br>") : "нет"]);
409	  const tech = Object.entries(t.technical || {});
410	  const calls = ev.calls.map(c => `<details class="call"><summary><code>${c.tool}</code> ${TOOLS[c.tool] || ""}
411	      <span class="${c.ok ? "" : "bad"}">${c.ok ? "✓" : "✗ ошибка"}</span><span class="ms">${c.ms} мс</span></summary>
412	      <pre>${esc(JSON.stringify({arguments: c.args, result: c.result}, null, 2))}</pre></details>`).join("");
413	  setCard("crm", "", `<div class="client"><b>${esc(u.name)}</b><span>${esc(u.role)} · ${esc(u.org)}</span></div>
414	    <dl class="facts">${rows.map(([k, v]) => `<dt>${k}</dt><dd>${v}</dd>`).join("")}</dl>
415	    <h3>Технические данные обращения</h3>
416	    ${tech.length ? `<dl class="tech">${tech.map(([k, v]) => `<dt>${esc(k)}</dt>
417	      <dd>${typeof v === "string" ? esc(v) : `<code>${esc(oneLine(v))}</code>`}</dd>`).join("")}</dl>`
418	      : `<div class="none">нет — вопрос о продукте</div>`}
419	    <details><summary>Вызовы MCP — ${ev.calls.length}</summary><div class="calls">${calls}</div></details>`);
420	}
421	
422	// ---------- ② база знаний ----------
423	function renderKb(ev) {
424	  hits = ev.hits;
425	  const idx = ev.index, errors = ev.queries.slice(1);
426	  $("kbHint").textContent = `${idx.model} · ${plural(idx.chunks, "фрагмент", "фрагмента", "фрагментов")} · ${dec(ev.seconds, 2)} с`;
427	  const quoted = errors.map(q => `«${esc(q)}»`).join(", ");
428	  const asked = errors.length ? `<div class="asked" title="${quoted}">Искали ещё по ошибке из обращения: ${quoted}</div>` : "";
429	  setCard("kb", "", asked + hits.map((h, i) => `<div class="hit" data-i="${i}">
430	      <div class="label"><span>${esc(h.file)} › ${esc(h.title)}</span><span class="score" title="косинусная близость">${dec(h.score, 2)}</span></div>
431	      <div class="text">${plain(h.text.replace(/^```.*\n?/gm, ""))}</div></div>`).join(""));
432	}
433	$("kbBody").addEventListener("click", e => { const h = e.target.closest(".hit"); if (h) h.classList.toggle("open"); });
434	
435	// ---------- ③ ответ клиенту ----------
436	function renderPrompt(ev) {
437	  $("answerHint").textContent = `${status?.model || "модель"} · этот компьютер`;
438	  renderPrompt.text = ev.messages.map(m => `— ${m.role} —\n${m.content}`).join("\n\n");
439	  renderPrompt.chars = ev.chars;
440	}
441	
442	const plain = s => esc(s).replace(/`([^`\n]+)`/g, "<code>$1</code>").replace(/\*\*([^*\n]+)\*\*/g, "<b>$1</b>");
443	
444	function markdown(text) {
445	  const inline = s => plain(s)
446	    .replace(/\[((?:FAQ|[^\[\]]+?\.md)(?: › [^\[\]]+)?)\]/g, (m, ref) => `<span class="cite" data-ref="${ref}">${ref}</span>`);
447	  const out = [];
448	  let list = null;
449	  for (const raw of text.split("\n")) {
450	    const line = raw.trim(), item = line.match(/^(?:[-*•]|\d+[.)])\s+(.*)$/);
451	    if (item) {
452	      const tag = /^\d/.test(line) ? "ol" : "ul";
453	      if (!list || list.tag !== tag) { if (list) out.push(`</${list.tag}>`); list = {tag}; out.push(`<${tag}>`); }
454	      out.push(`<li>${inline(item[1])}</li>`);
455	      continue;
456	    }
457	    if (list) { out.push(`</${list.tag}>`); list = null; }
458	    if (line) out.push(`<p>${inline(line)}</p>`);
459	  }
460	  if (list) out.push(`</${list.tag}>`);
461	  return out.join("");
462	}
463	
464	const cited = (ref, hit) => ref === `${hit.file} › ${hit.title}` || ref === hit.file;
465	
466	function renderAnswer(writing) {
467	  $("answerCard").className = `card answer-card ${writing ? "run" : ""}`;
468	  $("answerBody").innerHTML = `<div class="answer">${markdown(answerText)}${writing ? '<span class="cursor"></span>' : ""}</div>`;
469	  // фрагменты, на которые сослалась модель, обводятся во втором шаге
470	  const refs = [...$("answerBody").querySelectorAll(".cite")].map(c => c.dataset.ref);
471	  document.querySelectorAll(".hit").forEach(h => h.classList.toggle("cited", refs.some(r => cited(r, hits[+h.dataset.i]))));
472	}
473	
474	function renderStats(ev) {
475	  const load = ev.load > 0.5 ? ` · + загрузка модели <b>${dec(ev.load)}</b> с` : "";
476	  $("answerBody").insertAdjacentHTML("beforeend", `<div class="stats">
477	    <span><b>${dec(ev.seconds)}</b> с всего</span>
478	    <span>промпт <b>${ev.prompt}</b> токенов прочитан за <b>${dec(ev.reading)}</b> с</span>
479	    <span>ответ <b>${ev.tokens}</b> токенов, <b>${dec(ev.speed)}</b> токенов/сек${load}</span></div>
480	    <details><summary>Что ушло модели — ${renderPrompt.chars} знаков</summary><pre>${esc(renderPrompt.text || "")}</pre></details>`);
481	}
482	$("answerBody").addEventListener("click", e => {
483	  const c = e.target.closest(".cite");
484	  if (!c) return;
485	  const hit = [...document.querySelectorAll(".hit")].find(h => cited(c.dataset.ref, hits[+h.dataset.i]));
486	  if (hit) { hit.classList.add("open"); hit.scrollIntoView({behavior: "smooth", block: "center"}); }
487	});
488	
489	loadStatus();
490	</script>
491	</body>
492	</html>
